using UAF.Domain.Common;
namespace UAF.Domain.Enums { public enum NotificationChannel { InApp=1, Email=2, Sms=3 } public enum NotificationStatus { Pending=1, Sent=2, Failed=3, Read=4 } public enum WorkflowStatus { Pending=1, Approved=2, Rejected=3, Cancelled=4 } public enum WorkflowStepStatus { Pending=1, Approved=2, Rejected=3, Skipped=4 } }
namespace UAF.Domain.Entities {
using UAF.Domain.Enums;
public sealed class Notification : AuditableEntity {
 private Notification(){Title=Message=string.Empty;}
 public Notification(Guid userId,string title,string message,NotificationChannel channel){if(userId==Guid.Empty)throw new ArgumentException("Recipient is required.");if(string.IsNullOrWhiteSpace(title)||title.Trim().Length>160)throw new ArgumentException("Invalid title.");if(string.IsNullOrWhiteSpace(message)||message.Trim().Length>4000)throw new ArgumentException("Invalid message.");RecipientUserId=userId;Title=title.Trim();Message=message.Trim();Channel=channel;Status=channel==NotificationChannel.InApp?NotificationStatus.Sent:NotificationStatus.Pending;if(channel==NotificationChannel.InApp)SentAtUtc=DateTimeOffset.UtcNow;}
 public Guid RecipientUserId{get;private set;} public string Title{get;private set;} public string Message{get;private set;} public NotificationChannel Channel{get;private set;} public NotificationStatus Status{get;private set;} public DateTimeOffset? SentAtUtc{get;private set;} public DateTimeOffset? ReadAtUtc{get;private set;} public string? FailureReason{get;private set;}
 public void MarkSent(DateTimeOffset at){if(Status!=NotificationStatus.Pending)throw new InvalidOperationException("Only pending notifications can be sent.");Status=NotificationStatus.Sent;SentAtUtc=at.ToUniversalTime();}
 public void MarkFailed(string reason){if(Status!=NotificationStatus.Pending)throw new InvalidOperationException("Only pending notifications can fail.");FailureReason=string.IsNullOrWhiteSpace(reason)?"Delivery failed.":reason.Trim()[..Math.Min(500,reason.Trim().Length)];Status=NotificationStatus.Failed;}
 public void MarkRead(DateTimeOffset at){if(Channel!=NotificationChannel.InApp)throw new InvalidOperationException("Only in-app notifications can be read.");if(ReadAtUtc.HasValue)return;ReadAtUtc=at.ToUniversalTime();Status=NotificationStatus.Read;MarkUpdated(at);}
}
public sealed class WorkflowInstance : AuditableEntity {
 private WorkflowInstance(){ResourceType=string.Empty;}
 public WorkflowInstance(string type,Guid resourceId,Guid requester,int stages){if(string.IsNullOrWhiteSpace(type)||type.Trim().Length>100)throw new ArgumentException("Invalid resource type.");if(resourceId==Guid.Empty||requester==Guid.Empty)throw new ArgumentException("Resource and requester are required.");if(stages is <1 or >10)throw new ArgumentOutOfRangeException(nameof(stages));ResourceType=type.Trim();ResourceId=resourceId;RequestedByUserId=requester;TotalStages=stages;CurrentStage=1;Status=WorkflowStatus.Pending;}
 public string ResourceType{get;private set;} public Guid ResourceId{get;private set;} public Guid RequestedByUserId{get;private set;} public int CurrentStage{get;private set;} public int TotalStages{get;private set;} public WorkflowStatus Status{get;private set;} public DateTimeOffset? CompletedAtUtc{get;private set;}
 public void Advance(DateTimeOffset at){if(Status!=WorkflowStatus.Pending)throw new InvalidOperationException("Workflow is not pending.");if(CurrentStage>=TotalStages){Status=WorkflowStatus.Approved;CompletedAtUtc=at.ToUniversalTime();}else CurrentStage++;MarkUpdated(at);}
 public void Reject(DateTimeOffset at){if(Status!=WorkflowStatus.Pending)throw new InvalidOperationException("Workflow is not pending.");Status=WorkflowStatus.Rejected;CompletedAtUtc=at.ToUniversalTime();MarkUpdated(at);}
}
public sealed class WorkflowApprovalStep : AuditableEntity {
 private WorkflowApprovalStep(){RequiredRole=string.Empty;}
 public WorkflowApprovalStep(Guid workflowId,int sequence,string role,Guid? assigned=null){if(workflowId==Guid.Empty)throw new ArgumentException("Workflow required.");if(sequence is <1 or >10)throw new ArgumentOutOfRangeException(nameof(sequence));if(string.IsNullOrWhiteSpace(role)||role.Trim().Length>100)throw new ArgumentException("Role required.");if(assigned==Guid.Empty)throw new ArgumentException("Invalid assignee.");WorkflowInstanceId=workflowId;Sequence=sequence;RequiredRole=role.Trim();AssignedUserId=assigned;Status=WorkflowStepStatus.Pending;}
 public Guid WorkflowInstanceId{get;private set;} public int Sequence{get;private set;} public string RequiredRole{get;private set;} public Guid? AssignedUserId{get;private set;} public Guid? DecidedByUserId{get;private set;} public DateTimeOffset? DecidedAtUtc{get;private set;} public WorkflowStepStatus Status{get;private set;} public string? Comments{get;private set;}
 public void Decide(Guid actor,string role,bool approve,string? comments,DateTimeOffset at){if(Status!=WorkflowStepStatus.Pending)throw new InvalidOperationException("Step already decided.");if(actor==Guid.Empty)throw new ArgumentException("Approver required.");if(!string.Equals(RequiredRole,role,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Role cannot approve this stage.");if(AssignedUserId.HasValue&&AssignedUserId!=actor)throw new UnauthorizedAccessException("Step assigned to another user.");if(!approve&&string.IsNullOrWhiteSpace(comments))throw new ArgumentException("Rejection reason required.");DecidedByUserId=actor;DecidedAtUtc=at.ToUniversalTime();Comments=string.IsNullOrWhiteSpace(comments)?null:comments.Trim()[..Math.Min(2000,comments.Trim().Length)];Status=approve?WorkflowStepStatus.Approved:WorkflowStepStatus.Rejected;MarkUpdated(at);}
}
public sealed class WorkflowHistory : AuditableEntity {
 private WorkflowHistory(){ResourceType=FromState=ToState=string.Empty;}
 public WorkflowHistory(Guid workflowId,string type,Guid resourceId,Guid actor,string from,string to,string? comments,DateTimeOffset at){if(workflowId==Guid.Empty||resourceId==Guid.Empty||actor==Guid.Empty)throw new ArgumentException("IDs required.");WorkflowInstanceId=workflowId;ResourceType=Required(type,100);ResourceId=resourceId;ActorUserId=actor;FromState=Required(from,50);ToState=Required(to,50);Comments=string.IsNullOrWhiteSpace(comments)?null:comments.Trim()[..Math.Min(2000,comments.Trim().Length)];OccurredAtUtc=at.ToUniversalTime();}
 public Guid WorkflowInstanceId{get;private set;} public string ResourceType{get;private set;} public Guid ResourceId{get;private set;} public Guid ActorUserId{get;private set;} public string FromState{get;private set;} public string ToState{get;private set;} public string? Comments{get;private set;} public DateTimeOffset OccurredAtUtc{get;private set;}
 private static string Required(string v,int n)=>!string.IsNullOrWhiteSpace(v)&&v.Trim().Length<=n?v.Trim():throw new ArgumentException("Invalid workflow value.");
}
public sealed class AuditTrailEntry : AuditableEntity {
 private AuditTrailEntry(){Action=EntityType=string.Empty;}
 public AuditTrailEntry(Guid? actor,string action,string type,Guid entityId,string? beforeJson,string? afterJson,string? correlation,string? remoteIp,DateTimeOffset at){if(actor==Guid.Empty||entityId==Guid.Empty)throw new ArgumentException("Invalid audit identity.");ActorUserId=actor;Action=Required(action,30);EntityType=Required(type,150);EntityId=entityId;BeforeJson=beforeJson;AfterJson=afterJson;CorrelationId=Clip(correlation,100);RemoteIp=Clip(remoteIp,64);OccurredAtUtc=at.ToUniversalTime();}
 public Guid? ActorUserId{get;private set;} public string Action{get;private set;} public string EntityType{get;private set;} public Guid EntityId{get;private set;} public string? BeforeJson{get;private set;} public string? AfterJson{get;private set;} public string? CorrelationId{get;private set;} public string? RemoteIp{get;private set;} public DateTimeOffset OccurredAtUtc{get;private set;}
 private static string Required(string v,int n)=>!string.IsNullOrWhiteSpace(v)&&v.Trim().Length<=n?v.Trim():throw new ArgumentException("Invalid audit value.");private static string? Clip(string? v,int n)=>string.IsNullOrWhiteSpace(v)?null:v.Trim()[..Math.Min(n,v.Trim().Length)];
}
}